import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext.jsx';
import MainLayout from '../components/layout/MainLayout';
import GameConstructor from '../components/gameEngine/GameConstructor.jsx';

function HomePage() {
  const { currentUser, logout } = useAuth();
  const [showGameConstructor, setShowGameConstructor] = useState(false);

  const handleGenerateClick = () => {
    setShowGameConstructor(true);
   

  };

  return (
    <MainLayout>
      <div className="homepage">
        <h1>Добро пожаловать в WordPallete!</h1>
        <p>Привет, {currentUser?.email}!</p>
        <button onClick={logout} className="logout-btn">
          Выйти
        </button>

        <div className="features">
          <h2>Возможности приложения:</h2>
          <ul>
            <li>
              <button onClick={handleGenerateClick} className="feature-btn">
                Генерация креативных слов и фраз
              </button>
            </li>
            <li>Сохранение ваших любимых комбинаций</li>
            <li>Работа в разных категориях</li>
          </ul>
        </div>

        {/* Условный рендер GameConstructor */}
        {showGameConstructor && <GameConstructor />}
      </div>
    </MainLayout>
  );
}

export default HomePage;
